   370      inline bool transition (StateTableDriver<EntryData> *driver,
   371                              const Entry<EntryData> *entry)
   372      {
   373        hb_buffer_t *buffer = driver->buffer;
   374        unsigned int flags = entry->flags;
   375
   376        if (flags & SetComponent)
   377        {
   378          if (unlikely (match_length >= ARRAY_LENGTH (match_positions)))
   379            return false;
   380
   381          /* Never mark same index twice, in case DontAdvance was used... */
   382          if (match_length && match_positions[match_length - 1] == buffer->out_len)
   383            match_length--;
   384
   385          match_positions[match_length++] = buffer->out_len;
   386        }
   387
   388        if (flags & PerformAction)
   389        {
   390          unsigned int end = buffer->out_len;
   391          unsigned int action_idx = entry->data.ligActionIndex;
   392          unsigned int action;
   393          unsigned int ligature_idx = 0;
   394          do
   395          {
   396            if (unlikely (!match_length))
   397              return false;
   398
   399            buffer->move_to (match_positions[--match_length]);
   400
   401            const HBUINT32 &actionData = ligAction[action_idx];
   402            if (unlikely (!actionData.sanitize (&c->sanitizer))) return false;
   403            action = actionData;
   404
   405            uint32_t uoffset = action & LigActionOffset;
   406            if (uoffset & 0x20000000)
   407              uoffset += 0xC0000000;
   408            int32_t offset = (int32_t) uoffset;
   409            unsigned int component_idx = buffer->cur().codepoint + offset;
   410
   411            const HBUINT16 &componentData = component[component_idx];
   412            if (unlikely (!componentData.sanitize (&c->sanitizer))) return false;
   413            ligature_idx += componentData;
   414
   415            if (action & (LigActionStore | LigActionLast))
   416            {
   417              const GlyphID &ligatureData = ligature[ligature_idx];
   418              if (unlikely (!ligatureData.sanitize (&c->sanitizer))) return false;
   419              hb_codepoint_t lig = ligatureData;
   420
   421              match_positions[match_length++] = buffer->out_len;
   422              buffer->replace_glyph (lig);
   423
   424              //ligature_idx = 0; // XXX Yes or no?
   425            }
   426            else
   427            {
   428              buffer->skip_glyph ();
   429              end--;
   430            }
   431            /* TODO merge_clusters / unsafe_to_break */
   432
   433            action_idx++;
   434          }
   435          while (!(action & LigActionLast));
   436          buffer->move_to (end);
   437        }
   438
   439        return true;
   440      }
